\begin{tikzpicture}[font=\sffamily, line width=0.5pt]
  % title above the field
  \node at (4.5,5.5) {uniform magnetic field into the page};
  % region of uniform magnetic field, dashed
  \draw[dashed] (2,0) rectangle (7,5);
  % crosses showing the field into the page, none on the path
  \foreach \x in {4,5,6}
    \foreach \y in {0.5,1.5,2.5,3.5,4.5}
      \node at (\x,\y) {$\times$};
  % straight parts of the path with arrows
  \draw[-{Stealth[length=2.5mm]}] (0.5,4) -- (2,4);
  \draw[-{Stealth[length=2.5mm]}] (2,1) -- (0.5,1);
  % semicircular path inside the field, centre on the left edge
  \draw[line width=0.8pt] (2,4) arc[start angle=90, end angle=-90, radius=1.5];
  % centre of the semicircle with radius r
  \fill (2,2.5) circle (1.5pt);
  \draw (2,2.5) -- (3.5,2.5);
  \node[anchor=south] at (2.75,2.5) {$r$};
  % labels for the electron and its speed
  \node[anchor=south] at (1.25,4.1) {speed $v$};
  \node[anchor=north] at (1.25,3.9) {electron};
  % caption
  \node at (4.5,-0.8) {Fig. 3.1};
\end{tikzpicture}
